// Define stock universe to screen
// This could be customized or fetched from a database
const stockUniverse = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
  'META', 'TSLA', 'AMD', 'CRM', 'ADBE',
  'NFLX', 'PYPL', 'SHOP', 'SQ', 'SNOW'
];

return {
  symbols: stockUniverse,
  screening_date: new Date().toISOString().split('T')[0]
};

// Process and format results for storage
const results = $input.item.json;
const topPicks = results.top_picks || [];

return {
  screening_date: new Date().toISOString().split('T')[0],
  total_analyzed: results.stocks_ranked || 0,
  qualified_count: results.qualified_stocks || 0,
  top_picks: topPicks,
  summary: {
    best_pick: topPicks[0] || null,
    avg_score: topPicks.length > 0 
      ? topPicks.reduce((sum, s) => sum + s.score, 0) / topPicks.length 
      : 0
  }
};

// Generate email summary
const summary = $input.item.json.summary;
const topPicks = $input.item.json.top_picks;

const emailBody = `
<h2>Daily Stock Screening Results</h2>
<p><strong>Date:</strong> ${$input.item.json.screening_date}</p>
<p><strong>Stocks Analyzed:</strong> ${$input.item.json.total_analyzed}</p>
<p><strong>Qualified Stocks:</strong> ${$input.item.json.qualified_count}</p>

<h3>Top Picks:</h3>
<ol>
${topPicks.slice(0, 5).map(stock => `
  <li>
    <strong>${stock.symbol} - ${stock.company_name}</strong><br>
    Score: ${stock.score.toFixed(2)}<br>
    Recommendation: ${stock.ai_recommendation}<br>
    Growth: ${(stock.fundamentals.revenue_growth * 100).toFixed(2)}%
  </li>
`).join('')}
</ol>
`;

return {
  subject: `Stock Screening Results - ${$input.item.json.screening_date}`,
  body: emailBody
};
